n(echo_circ) // 2].draw("mpl")  # draw a sample circuit\n'})}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{className:"language-text",children:"Echo sweep: 0..1240 us in 24 points\n"})}),"\n",(0,i.jsx)(e.p,{children:(0,i.jsx)(e.img,{alt:"Output of the previous code cell",src:a(84816).A+"",width:"613",height:"174"})}),"\n",(0,i.jsx)(e.h3,{id:"analyze-fit-and-compare-the-two-decays",children:"Analisi: adattare e confrontare i due decadimenti"}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{className:"language-python",children:'# Initial guesses / bounds derived from the reported coherence so the fits track the scaled axes.\nT2_us = (backend.qubit_properties(QUBIT).t2 or 100e-6) * 1e6\n\n# Ramsey: decaying oscillation -> extract T2*\ndef ramsey_fn(t, A, T2s, f, phi, B):\n    return A * np.exp(-t / T2s) * np.cos(2 * np.pi * f * t + phi) + B\n\nrp0 = [0.4, T2_us / 2, f_detune * 1e-6, 0.0, 0.5]  # T2* guess ~ half the echo T2\nrbounds = (\n    [0, 0.1, 0, -np.pi, 0],\n    [1, 2 * T2_us, 5, np.pi, 1],\n)  # keep the fit from collapsing to ~0\nrpopt, _ = curve_fit(\n    ramsey_fn, ramsey_delays_us, p1_ramsey, p0=rp0, bounds=rbounds, maxfev=20000\n)\nT2_star = abs(rpopt[1])\n\n# Echo: simple exponential envelope -> extract T2\ndef env(t, A, T2, B):\n    return A * np.exp(-t / T2) + B\n\nepopt, _ = curve_fit(env, echo_delays_us, p1_echo, p0=[0.5, T2_us, 0.0], maxfev=10000)\nT2 = abs(epopt[1])\n\nfig, ax = plt.subplots(1, 2, figsize=(12, 4))\nax[0].plot(ramsey_delays_us, p1_ramsey, "o")\ntt = np.linspace(0, ramsey_delays_us.max(), 400)\nax[0].plot(tt, ramsey_fn(tt, *rpopt), "-")\nax[0].set_title(rf"Ramsey: $T_2^*$ = {T2_star:.1f} \xb5s")\nax[0].set_xlabel("\u03c4 (\xb5s)")\nax[0].set_ylabel(r"$P_1$")\nax[1].plot(echo_delays_us, p1_echo, "o")\ntt2 = np.linspace(0, echo_delays_us.max(), 400)\nax[1].plot(tt2, env(tt2, *epopt), "-")\nax[1].set_title(rf"Hahn echo: $T_2$ = {T2:.1f} \xb5s")\nax[1].set_xlabel("\u03c4 (\xb5s)")\nplt.tight_layout()\nplt.show()\nprint(f"T2* (Ramsey) = {T2_star:.1f} \xb5s ;  T2 (echo) = {T2:.1f} \xb5s")\n'})}),"\n",(0,i.jsx)(e.p,{children:(0,i.jsx)(e.img,{alt:"Output of the previous code cell",src:a(52308).A+"",width:"1189",height:"390"})}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{className:"language-text",children:"T2* (Ramsey) = 171.2 \xb5s ;  T2 (echo) = 326.0 \xb5s\n"})}),"\n",(0,i.jsxs)(e.p,{children:["Qui vediamo decadere sia l'oscillazione di Ramsey sia il segnale dell'eco di Hahn, come previsto. Le scale temporali associate a ciascuno di questi decadimenti sono rispettivamente ",(0,i.jsxs)(e.span,{className:"katex",children:[(0,i.jsx)(e.span,{className:"katex-mathml",children:(0,i.jsx)(e.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:(0,i.jsxs)(e.semantics,{children:[(0,i.jsx)(e.mrow,{children:(0,i.jsxs)(e.msubsup,{children:[(0,i.jsx)(e.mi,{children:"T"}),(0,i.jsx)(e.mn,{children:"2"}),(0,i.jsx)(e.mo,{children:"\u2217"})]})}),(0,i.jsx)(e.annotation,{encoding:"application/x-tex",children:"T_2^*"})]})})}),(0,i.jsx)(e.span,{className:"katex-html","aria-hidden":"true",children:(0,i.jsxs)(e.span,{className:"base",children:[(0,i.jsx)(e.span,{className:"strut",style:{height:"0.9368em",verticalAlign:"-0.2481em"}}),(0,i.jsxs)(e.span,{className:"mord",children:[(0,i.jsx)(e.span,{className:"mord mathnormal",style:{marginRight:"0.13889em"},children:"T"}),(0,i.jsx)(e.span,{className:"msupsub",children:(0,i.jsxs)(e.span,{className:"vlist-t vlist-t2",children:[(0,i.jsxs)(e.span,{className:"vlist-r",children:[(0,i.jsxs)(e.span,{className:"vlist",style:{height:"0.6887em"},children:[(0,i.jsxs)(e.span,{style:{top:"-2.4519em",marginLeft:"-0.1389em",marginRight:"0.05em"},children:[(0,i.jsx)(e.span,{className:"pstrut",style:{height:"2.7em"}}),(0,i.jsx)(e.span,{className:"sizing reset-size6 size3 mtight",children:(0,i.jsx)(e.span,{className:"mord mtight",children:"2"})})]}),(0,i.jsxs)(e.span,{style:{top:"-3.063em",marginRight:"0.05em"},children:[(0,i.jsx)(e.span,{className:"pstrut",style:{height:"2.7em"}}